//! C-alignment regression tests (step H5: the FTS5 write path as a port of ext/fts5 — pending-terms hash, flush points,
//! segment writer, doclist index, automerge / crisis merge / promotion, incremental merges, secure delete, tombstones,
//! special commands, transaction hooks — and the host rules that make it observable). GENERATED by
//! target/perf-work/h5/gen_tests5.py: every expected value is what C SQLite 3.54.1 produces — size and FNV-1a hash of
//! the database file C writes for the statements, and the rows / error messages C returns (shadow-table dumps,
//! changes(), total_changes(), last_insert_rowid(), EXPLAIN QUERY PLAN text, integrity-check messages). Every case
//! fails with the code before step H5 (own segment schedule, a flush on every read, nested statements not counted,
//! own plan encoding); nothing here depends on files outside the repository.
use crate::Connection;

fn fnv1a(bytes: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        h = (h ^ u64::from(b)).wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-h5-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm"] {
            let mut s = self.0.clone().into_os_string();
            s.push(suffix);
            let _ = std::fs::remove_file(std::path::PathBuf::from(s));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

fn assert_file_is_what_c_writes(name: &str, stmts: &[&str], c_size: usize, c_hash: u64) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    for sql in stmts {
        // (a statement may fail, as it does in the C shell that produced the expected file:
        // the script goes on)
        let _ = conn.query(sql, &[]);
    }
    assert!(conn.try_close().is_ok());
    let bytes = std::fs::read(&db.0).unwrap();
    assert_eq!(bytes.len(), c_size, "{name}: file size");
    assert_eq!(fnv1a(&bytes), c_hash, "{name}: file content differs from C");
}

/// Runs the statements; `c_out` is what the C shell prints for them (rows as `a|b`, one per line; the lines of an
/// EXPLAIN QUERY PLAN are its `detail` column), `c_errors` the messages of the statements that fail, in order.
fn assert_rows_and_errors_are_what_c_returns(
    name: &str,
    stmts: &[&str],
    c_out: &str,
    c_errors: &[&str],
) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    let mut out = String::new();
    let mut errors: Vec<String> = Vec::new();
    for sql in stmts {
        let eqp = sql.starts_with("EXPLAIN QUERY PLAN");
        match conn.query(sql, &[]) {
            Ok(res) => {
                for row in &res.rows {
                    let cells: Vec<String> = row
                        .values
                        .iter()
                        .map(|v| match v {
                            sqliters_types::Value::Null => String::new(),
                            sqliters_types::Value::Integer(i) => i.to_string(),
                            sqliters_types::Value::Real(r) => format!("{r:?}"),
                            sqliters_types::Value::Text(s) => s.to_string(),
                            sqliters_types::Value::Blob(b) => {
                                String::from_utf8_lossy(&b[..]).into_owned()
                            }
                        })
                        .collect();
                    if eqp {
                        out.push_str(cells.last().map_or("", String::as_str));
                    } else {
                        out.push_str(&cells.join("|"));
                    }
                    out.push('\n');
                }
            }
            Err(e) => errors.push(e.message.clone()),
        }
    }
    assert!(conn.try_close().is_ok());
    assert_eq!(out, c_out, "{name}: rows");
    assert_eq!(errors, c_errors, "{name}: error messages");
}

