/// one transaction: the pending-terms hash is written in key order (`fts5WriteAppendTerm` prefix compression, page footer, leaves of `pgsz` 4050 bytes, `%_idx` split keys); the doclist of a term in every row spans leaves and gets a doclist index (`fts5WriteDlidxAppend`, bit 0 of `%_idx.pgno`).
#[test]
fn fts5_one_transaction_leaf_layout_and_doclist_index() {
    assert_file_is_what_c_writes(
        "fts5_one_transaction_leaf_layout_and_doclist_index",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<6000) INSERT INTO ft(rowid, a, b) SELECT x, 'w'||(x%7)||' v'||(x%31)||' u'||(x%211)||' t'||x||' common', 'p'||(x%5)||' q'||(x%13) FROM c;",
            "COMMIT;",
        ],
        507904,
        0x7b074952d9833ec8,
    );
}

