/// prefix indexes (`sqlite3Fts5IndexWrite` adds one hash entry per prefix index) and the position lists of detail=column / detail=none.
#[test]
fn fts5_prefix_indexes_detail_column_and_none() {
    assert_file_is_what_c_writes(
        "fts5_prefix_indexes_detail_column_and_none",
        &[
            "CREATE VIRTUAL TABLE f1 USING fts5(a, b, prefix='1 2 3');",
            "CREATE VIRTUAL TABLE f2 USING fts5(a, b, detail=column, prefix=2);",
            "CREATE VIRTUAL TABLE f3 USING fts5(a, b, detail=none);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<500) INSERT INTO f1(rowid, a, b) SELECT x, 'w'||(x%7)||' v'||(x%31)||' u'||(x%211)||' t'||x||' common', 'p'||(x%5)||' q'||(x%13) FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<500) INSERT INTO f2(rowid, a, b) SELECT x, 'w'||(x%7)||' v'||(x%31)||' u'||(x%211)||' t'||x||' common', 'p'||(x%5)||' q'||(x%13) FROM c;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<500) INSERT INTO f3(rowid, a, b) SELECT x, 'w'||(x%7)||' v'||(x%31)||' u'||(x%211)||' t'||x||' common', 'p'||(x%5)||' q'||(x%13) FROM c;",
            "COMMIT;",
            "DELETE FROM f1 WHERE rowid % 9 = 1;",
            "UPDATE f2 SET a = 'changed' WHERE rowid % 10 = 0;",
            "DELETE FROM f3 WHERE rowid < 50;",
            "UPDATE f3 SET b = a WHERE rowid % 13 = 0;",
        ],
        266240,
        0xf8db1fce778fe8be,
    );
}

/// xSavepoint flushes the pending data before the statement savepoint is opened (`OP_Transaction`: `sqlite3VtabSavepoint` before `sqlite3BtreeBeginStmt`): a statement that fails and is rolled back does not take the rows of earlier statements with it; SAVEPOINT / ROLLBACK TO / RELEASE inside the transaction.
#[test]
fn fts5_flush_before_statement_savepoint_survives_rollback() {
    assert_file_is_what_c_writes(
        "fts5_flush_before_statement_savepoint_survives_rollback",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<40) INSERT INTO ft(rowid, a, b) SELECT x, 'w'||(x%7)||' v'||(x%31)||' u'||(x%211)||' t'||x||' common', 'p'||(x%5)||' q'||(x%13) FROM c;",
            "BEGIN;",
            "INSERT INTO ft VALUES('first pending', 'x');",
            "INSERT INTO ft(rowid, a, b) SELECT value, 'dup', 'dup' FROM json_each('[200, 201, 3, 202]');",
            "INSERT INTO ft VALUES('second pending', 'y');",
            "SAVEPOINT s1;",
            "INSERT INTO ft VALUES('in savepoint', 'z');",
            "DELETE FROM ft WHERE rowid < 5;",
            "ROLLBACK TO s1;",
            "INSERT INTO ft VALUES('after rollback to', 'q');",
            "SAVEPOINT s2;",
            "UPDATE ft SET b = 'upd' WHERE rowid % 3 = 0;",
            "RELEASE s2;",
            "RELEASE s1;",
            "INSERT INTO ft VALUES('last', 'w');",
            "COMMIT;",
        ],
        24576,
        0xd472ad910866c3ad,
    );
}

/// 'rebuild' and 'delete-all' of an external-content table at page size 512 (`sqlite3Fts5StorageDeleteAll`, `sqlite3Fts5IndexReinit`, the rows re-indexed in scan order, totals saved by the rebuild and again at xSync).
#[test]
fn fts5_rebuild_delete_all_external_content_512() {
    assert_file_is_what_c_writes(
        "fts5_rebuild_delete_all_external_content_512",
        &[
            "PRAGMA page_size=512;",
            "CREATE TABLE src(id INTEGER PRIMARY KEY, a, b);",
            "CREATE VIRTUAL TABLE ft USING fts5(a, b, content='src', content_rowid='id');",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<700) INSERT INTO src SELECT x, 'w'||(x%7)||' v'||(x%31)||' u'||(x%211)||' t'||x||' common', 'p'||(x%5)||' q'||(x%13) FROM c;",
            "INSERT INTO ft(ft) VALUES('rebuild');",
            "DELETE FROM src WHERE id % 3 = 0;",
            "INSERT INTO ft(ft) VALUES('rebuild');",
            "INSERT INTO ft(ft) VALUES('delete-all');",
            "INSERT INTO ft(ft) VALUES('rebuild');",
        ],
        61440,
        0xdc2832586ea1f100,
    );
}

/// 'hashsize' reached inside a statement (`nPendingData > nHashSize`), 'automerge' / 'crisismerge' / 'usermerge' / 'deletemerge' / 'rank' values: the `%_config` rows and the cookie written in place into the structure record.
#[test]
fn fts5_hashsize_flush_inside_a_statement_and_config_values() {
    assert_file_is_what_c_writes(
        "fts5_hashsize_flush_inside_a_statement_and_config_values",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft(ft, rank) VALUES('hashsize', 4000);",
            "INSERT INTO ft(ft, rank) VALUES('automerge', 2);",
            "INSERT INTO ft(ft, rank) VALUES('crisismerge', 3);",
            "INSERT INTO ft(ft, rank) VALUES('usermerge', 2);",
            "INSERT INTO ft(ft, rank) VALUES('rank', 'bm25(2.0, 1.0)');",
            "INSERT INTO ft(ft, rank) VALUES('deletemerge', 20);",
            "BEGIN;",
            "WITH RECURSIVE c(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM c WHERE x<1500) INSERT INTO ft(rowid, a, b) SELECT x, 'w'||(x%7)||' v'||(x%31)||' u'||(x%211)||' t'||x||' common', 'p'||(x%5)||' q'||(x%13) FROM c;",
            "COMMIT;",
            "INSERT INTO ft(ft, rank) VALUES('merge', 4);",
        ],
        172032,
        0x20f646ccdd971311,
    );
}

